// Pre-push secret scan. Prints locations and kinds only, never the matched values.
// Usage: node secretscan.mjs <repoRoot> <file> [file...]
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";

const root = process.argv[2];
const files = process.argv.slice(3);
const require = createRequire(path.join(root, "package.json"));
const { wordlists } = require("ethers");
const en = wordlists.en;
const BIP39 = new Set(Array.from({ length: 2048 }, (_, i) => en.getWord(i)));

// Dev-key hashes are taken from the archive hook, so this script holds no keys either.
const hook = fs.readFileSync(path.join(root, ".claude/hooks/archive_transcript.mjs"), "utf8");
const DEV = new Set(hook.match(/"[0-9a-f]{64}"/g).map((s) => s.slice(1, -1)));
if (DEV.size !== 20) throw new Error(`expected 20 dev-key hashes, got ${DEV.size}`);

const sha = (s) => createHash("sha256").update(s).digest("hex");
const HEX64 = /(?<![0-9A-Fa-f])(0x)?([0-9A-Fa-f]{64})(?![0-9A-Fa-f])/g;
const EMAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const DEV_PHRASE = /\btest(?:\s+test){10}\s+junk\b/gi;
const RPC = [
  /infura\.io\/v3\/[0-9a-fA-F]{20,}/g,
  /alchemy(?:api)?\.(?:com|io)\/v2\/[A-Za-z0-9_-]{16,}/g,
  /quiknode\.pro\/[A-Za-z0-9]{20,}/g,
  /rpc\.ankr\.com\/[a-z_]+\/[0-9a-f]{32,}/g,
  /(?:api[_-]?key|apikey|access[_-]?token|secret)\s*["']?\s*[:=]\s*["']?[A-Za-z0-9_-]{20,}/gi,
  /(?:PRIVATE_KEY|SEPOLIA_KEY_[A-D])\s*["']?\s*[:=]\s*["']?(?:0x)?[0-9a-fA-F]{64}/g,
];
// Benign email-shaped strings: package scopes / git-style refs that are not addresses.
const benignEmail = (m) =>
  m.endsWith("@users.noreply.github.com") || /^[^@]+@\d+\.\d+/.test(m) || /@(example|anthropic)\.(com|org)$/.test(m) === false && false;

let findings = 0;
const report = (f, idx, kind, value) => {
  findings++;
  console.log(`${f}\t@${idx}\t${kind}\tsha256:${sha(value).slice(0, 12)}\tlen:${value.length}`);
};

for (const f of files) {
  let text;
  try { text = fs.readFileSync(path.join(root, f), "utf8"); } catch { continue; }

  for (const m of text.matchAll(HEX64)) if (DEV.has(sha(m[2].toLowerCase()))) report(f, m.index, "hardhat-dev-key", m[2]);
  for (const m of text.matchAll(DEV_PHRASE)) report(f, m.index, "hardhat-dev-mnemonic", m[0]);
  for (const m of text.matchAll(EMAIL)) if (!benignEmail(m[0])) report(f, m.index, "email", m[0]);
  for (const re of RPC) for (const m of text.matchAll(re)) report(f, m.index, `rpc/api-key:${re.source.slice(0, 18)}`, m[0]);

  // Any run of 12+ consecutive BIP-39 words (a possible seed phrase).
  const words = [...text.matchAll(/[a-z]+/g)];
  let run = [];
  const flush = () => { if (run.length >= 12) report(f, run[0].index, `bip39-run-${run.length}`, run.map((w) => w[0]).join(" ")); run = []; };
  for (const w of words) {
    const prev = run.at(-1);
    const gapOk = !prev || /^[\s\\n"',]*$/.test(text.slice(prev.index + prev[0].length, w.index)) && w.index - (prev.index + prev[0].length) <= 3;
    if (BIP39.has(w[0]) && gapOk) run.push(w);
    else { flush(); if (BIP39.has(w[0])) run.push(w); }
  }
  flush();
}
console.log(`scanned ${files.length} files, ${findings} findings`);
process.exit(findings ? 1 : 0);

