2	import { targetNetwork } from "../config/networks";
3	import type { WalletProvider } from "../types";
4	export async function walletSnapshot(
5	  provider: WalletProvider,
6	  connect = false,
7	) {
8	  const accounts: string[] = await provider.request({
9	    method: connect ? "eth_requestAccounts" : "eth_accounts",
10	  });
11	  const chain = await provider.request({ method: "eth_chainId" });
12	  return { account: accounts[0] || null, chainId: Number(BigInt(chain)) };
13	}
14	export async function switchNetwork(provider: WalletProvider) {
15	  const chainId = toQuantity(targetNetwork.chainId);
16	  try {
17	    await provider.request({
18	      method: "wallet_switchEthereumChain",
19	      params: [{ chainId }],
20	    });
21	  } catch (error: any) {
22	    if (error?.code !== 4902 && error?.info?.error?.code !== 4902) throw error;
23	    await provider.request({
24	      method: "wallet_addEthereumChain",
25	      params: [
26	        {
27	          chainId,
28	          chainName: targetNetwork.name,
29	          rpcUrls: [targetNetwork.rpcUrl],
30	          nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
31	        },
32	      ],
33	    });
34	    await provider.request({
35	      method: "wallet_switchEthereumChain",
36	      params: [{ chainId }],
37	    });
38	  }
39	}
