1	import { expect } from "chai";
2	import hre from "hardhat";
3	import { readFileSync } from "node:fs";
4	
5	const scripts: Record<string, string> = JSON.parse(readFileSync("package.json", "utf8")).scripts;
6	
7	// `hardhat run`, `test` and `compile` use the "default" profile unless --build-profile is given.
8	function profileOf(command: string): string {
9	  return /--build-profile[ =](\S+)/.exec(command)?.[1] ?? "default";
10	}
11	
12	function expectOptimised(profileName: string, context: string) {
13	  const profile = hre.config.solidity.profiles[profileName];
14	  expect(profile, `${context}: build profile "${profileName}" exists`).to.not.equal(undefined);
15	  const compilers = [...profile.compilers, ...Object.values(profile.overrides)];
16	  expect(compilers.length).to.be.greaterThan(0);
17	  for (const compiler of compilers) {
18	    expect(compiler.settings?.optimizer?.enabled, `${context}: "${profileName}" solc ${compiler.version} optimizer`).to.equal(true);
19	  }
20	}
21	
22	// AUD-012: AssetFactory embeds the AssetToken and AssetSale creation code. Unoptimised,
23	// it is exactly 24576 bytes, the EIP-170 limit, so any further change makes it
24	// undeployable.
25	describe("AUD-012 Sepolia deployment build profile", function () {
26	  it("deploy:sepolia builds with a profile that enables the optimizer for every compiler", function () {
27	    expectOptimised(profileOf(scripts["deploy:sepolia"]), "deploy:sepolia");
28	  });
29	});
30	
31	// AUD-014: AUD-012 fixed only the Sepolia path. Tests, local deploys, the demo seed
32	// and the integration test (which deploys straight from artifacts/) still built the
33	// 24576-byte factory.
34	describe("AUD-014 every Hardhat build path", function () {
35	  it("every npm script that compiles through hardhat run, test or compile uses an optimised profile", function () {
36	    const building = Object.entries(scripts).flatMap(([name, script]) =>
37	      script
38	        .split("&&")
39	        .filter((command) => /\bhardhat\b[^&]*\b(run|test|compile)\b/.test(command))
40	        .map((command) => [name, command.trim()] as const),
41	    );
42	    expect(building.map(([name]) => name)).to.include.members(["test", "compile", "deploy:local", "deploy:sepolia"]);
43	    for (const [name, command] of building) expectOptimised(profileOf(command), `npm run ${name}`);
44	  });
45	});
