// Throwaway experiment (not committed): how does a reverting tx with a fixed gas limit behave in-process?
import { network } from "hardhat";
const { ethers } = await network.getOrCreate();
const [a, b, c, d] = await ethers.getSigners();
const f = await ethers.deployContract("AssetFactory", [a.address]);
await (await f.authorizeIssuer(b.address)).wait();
await (await f.connect(b).createAsset("X", "X", "", 0n, 100n, 1n)).wait();
const t = await ethers.getContractAt("AssetToken", (await f.getAsset(0n)).tokenContract, b);
await (await t.setWhitelisted(c.address, true)).wait();
await (await t.transfer(c.address, 10n)).wait();
try {
  const tx = await t.connect(c).transfer(d.address, 5n, { gasLimit: 100_000n });
  console.log("sent", tx.hash);
  try { const r = await tx.wait(); console.log("wait ok", r?.status); }
  catch (e: any) { console.log("wait threw", e.code, "receipt status", e.receipt?.status, "gasUsed", e.receipt?.gasUsed); }
} catch (e: any) {
  console.log("send threw", e.code, e.shortMessage ?? e.message?.slice(0, 200));
  console.log("keys", Object.keys(e), "txHash?", e.transactionHash ?? e.data?.transactionHash);
  console.log("block", await ethers.provider.getBlockNumber(), "c nonce", await ethers.provider.getTransactionCount(c.address));
}

