const fs = require("fs");
const path = require("path");
const root = process.argv[2];
console.log(["AssetFactory", "AssetToken", "AssetSale"].map((n) => {
  const a = JSON.parse(fs.readFileSync(path.join(root, "artifacts/contracts", `${n}.sol`, `${n}.json`), "utf8"));
  const b = (a.deployedBytecode.length - 2) / 2;
  return `${n} ${b} (${((100 * b) / 24576).toFixed(1)}%)`;
}).join(", "));

